import{_ as t,o as d,c as a,a0 as o}from"./chunks/framework.BJ26GviO.js";const u=JSON.parse('{"title":"Tool reference","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tools.md","filePath":"guide/tools.md"}'),r={name:"guide/tools.md"};function c(i,e,s,n,h,l){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="tool-reference" tabindex="-1">Tool reference <a class="header-anchor" href="#tool-reference" aria-label="Permalink to &quot;Tool reference&quot;">​</a></h1><p>Every tool and parameter, so you can audit the surface area.</p><h2 id="web-search" tabindex="-1">web_search <a class="header-anchor" href="#web-search" aria-label="Permalink to &quot;web_search&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>required</td></tr><tr><td><code>max_results</code></td><td>number</td><td>1–20, default 8</td></tr><tr><td><code>recency</code></td><td>string</td><td><code>d</code> day · <code>w</code> week · <code>m</code> month · <code>y</code> year</td></tr><tr><td><code>engine</code></td><td>string</td><td><code>ddg</code> (default) · <code>brave</code> · <code>bing</code> · <code>multi</code> (parallel, RRF-fused)</td></tr><tr><td><code>deep</code></td><td>boolean | number</td><td>read top results, attach query-relevant excerpts. <code>true</code> = 4, or 1–8</td></tr><tr><td><code>refresh</code></td><td>boolean</td><td>skip the 10-minute cache</td></tr></tbody></table><p>Rows include the URL, publication date when the engine provides one, and a <code>via</code> line showing which engines served the results. Deep rows show an <code>excerpt:</code> line per result.</p><p>Fallback chain: DDG html → DDG lite → DDG POST → r.jina.ai proxy → Bing RSS. Any primary-engine failure auto-retries through <code>multi</code>.</p><h2 id="fetch-page" tabindex="-1">fetch_page <a class="header-anchor" href="#fetch-page" aria-label="Permalink to &quot;fetch_page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>url</code></td><td>string</td><td>http/https only (SSRF-guarded)</td></tr><tr><td><code>query</code></td><td>string</td><td>returns intro + most query-relevant passages (BM25) instead of the page head</td></tr><tr><td><code>max_chars</code></td><td>number</td><td>default 8000, max 50000</td></tr><tr><td><code>raw</code></td><td>boolean</td><td>return raw HTML instead of extracted markdown</td></tr><tr><td><code>timeout</code></td><td>number</td><td>1000–60000 ms</td></tr><tr><td><code>headers</code></td><td>object</td><td>custom request headers</td></tr><tr><td><code>no_cache</code> / <code>no_wayback</code> / <code>allow_http_errors</code></td><td>boolean</td><td>escape hatches</td></tr></tbody></table><p>Handles HTML (markdown extraction), JSON (pretty-printed), plain text and PDFs (poppler if installed, internal parser otherwise). Bot-walls retry via the Wayback Machine; thin/SPA pages re-render through a reader proxy. The output header reports the source: <code>direct</code>, <code>wayback</code>, <code>jina</code>, <code>github-issue-api</code>, <code>stackexchange-api</code>, <code>wikipedia-rest</code>, …</p><h3 id="site-adapters" tabindex="-1">Site adapters <a class="header-anchor" href="#site-adapters" aria-label="Permalink to &quot;Site adapters&quot;">​</a></h3><p>Known URL shapes skip scraping entirely:</p><ul><li><code>github.com/{o}/{r}</code> — API metadata + raw README</li><li><code>github.com/{o}/{r}/issues|pull/{n}</code> — issue/PR + comments as markdown</li><li><code>github.com/{o}/{r}/blob/{ref}/{path}</code> — raw file</li><li><code>stackoverflow.com/questions/{id}</code> — question + top answers</li><li><code>news.ycombinator.com/item?id=</code> — thread via Algolia</li><li><code>reddit.com/.../comments/...</code> — post + top comments via <code>.json</code></li><li><code>wikipedia.org/wiki/{title}</code> — REST html → markdown</li></ul><h2 id="search-stackoverflow-search-wikipedia-search-npm-search-github-search-hn" tabindex="-1">search_stackoverflow / search_wikipedia / search_npm / search_github / search_hn <a class="header-anchor" href="#search-stackoverflow-search-wikipedia-search-npm-search-github-search-hn" aria-label="Permalink to &quot;search_stackoverflow / search_wikipedia / search_npm / search_github / search_hn&quot;">​</a></h2><p>Single <code>query</code> (+ <code>max</code>) each. All free APIs, no keys; <code>search_github</code> honours an optional <code>GITHUB_TOKEN</code> env var for rate limits.</p><h2 id="research-topic" tabindex="-1">/research <code>&lt;topic&gt;</code> <a class="header-anchor" href="#research-topic" aria-label="Permalink to &quot;/research `&lt;topic&gt;`&quot;">​</a></h2><p>Runs web + HN + GitHub + Wikipedia searches in parallel with live footer progress, fetches the most promising pages, then asks the model for a grouped briefing: documents worth reading, recurring conclusions, and disagreements between sources.</p>',16)])])}const m=t(r,[["render",c]]);export{u as __pageData,m as default};
